namespace Firefall.Reconstruction.Startup;

public enum NativeGeneratedProviderReleaseKind
{
    RngDeletingDestructorSlot4WithArgument1,
    FreeTableAllocation,
    ReturnFirstOutputToArena,
    ReturnSecondOutputToArena
}

public readonly record struct NativeGeneratedProviderReleaseStep(
    NativeGeneratedProviderReleaseKind Kind, uint CapturedAddress);

/// <summary>Captured lifetime/ABI facts only. Does not invoke thunks, deleting destructors, native free or generated bytes.</summary>
public static class NativeGeneratedProviderLifetimePlan
{
    public const uint DestructorFileOffset = 0x12850F0;
    public const uint EquivalentDestructorFileOffset = 0x1285140;
    public const uint FirstTailThunkFileOffset = 0x1285120;
    public const uint SecondTailThunkFileOffset = 0x1285130;
    public const uint FirstOutputPointerOffset = 0x10;
    public const uint SecondOutputPointerOffset = 0x14;
    public const uint ArenaHeaderDistanceBeforeOutput = 16;
    public const uint CallbackBufferStackOffsetFromEbp = 8;
    public const uint CallbackCountStackOffsetFromEbp = 12;
    public const uint CallbackStackBytesPopped = 8;
    public const uint IncomingConsumerFileOffset = 0x124B3F0;
    public const uint IncomingCallbackCallFileOffset = 0x124B48D;
    public const uint OutgoingConsumerFileOffset = 0x124E010;
    public const uint OutgoingCallbackCallFileOffset = 0x124E085;
    public const bool ObservedConsumersUseCallbackReturnValue = false;

    public static IReadOnlyList<NativeGeneratedProviderReleaseStep> FromCapturedPointers(
        uint rngAddress, uint tableAddress, uint firstOutputAddress, uint secondOutputAddress)
    {
        var steps = new List<NativeGeneratedProviderReleaseStep>(4);
        if (rngAddress != 0)
            steps.Add(new(NativeGeneratedProviderReleaseKind.RngDeletingDestructorSlot4WithArgument1, rngAddress));
        if (tableAddress != 0)
            steps.Add(new(NativeGeneratedProviderReleaseKind.FreeTableAllocation, tableAddress));
        steps.Add(new(NativeGeneratedProviderReleaseKind.ReturnFirstOutputToArena, firstOutputAddress));
        steps.Add(new(NativeGeneratedProviderReleaseKind.ReturnSecondOutputToArena, secondOutputAddress));
        return steps.AsReadOnly();
    }
}
